import pytest

def is_samepatterns(colors, patterns):
    if len(colors) != len(patterns):
        return False    
    pattern_color_dict = {pattern: set() for pattern in patterns}
    for color, pattern in zip(colors, patterns):
        pattern_color_dict[pattern].add(color)
    return all(len(pattern_color_dict[pattern]) == 1 for pattern in patterns)

def test_is_samepatterns_normal():
    colors = ['red', 'blue', 'green']
    patterns = ['A', 'B', 'C']
    assert is_samepatterns(colors, patterns) == True

def test_is_samepatterns_boundary():
    colors = ['red', 'blue', 'green']
    patterns = ['A', 'A', 'A']
    assert is_samepatterns(colors, patterns) == True

def test_is_samepatterns_error():
    colors = ['red', 'blue', 'green']
    patterns = ['A', 'B', 'A']
    assert is_samepatterns(colors, patterns) == False

def test_is_samepatterns_empty():
    colors = []
    patterns = []
    assert is_samepatterns(colors, patterns) == True

def test_is_samepatterns_single_color():
    colors = ['red']
    patterns = ['A']
    assert is_samepatterns(colors, patterns) == True

def test_is_samepatterns_single_pattern():
    colors = ['red', 'blue', 'green']
    patterns = ['A']
    assert is_samepatterns(colors, patterns) == False

def test_is_samepatterns_different_length():
    colors = ['red', 'blue']
    patterns = ['A', 'B', 'C']
    assert is_samepatterns(colors, patterns) == False

def test_is_samepatterns_different_colors():
    colors = ['red', 'blue', 'green']
    patterns = ['A', 'B', 'C']
    assert is_samepatterns(colors, patterns) == False
