    # Single element dictionary
    input_dict = {'x': 5}
    expected_output = [('x', 5)]
    assert sort_counter(input_dict) == expected_output

def test_sort_counter_empty_dict():
    # Empty dictionary
    input_dict = {}
    expected_output = []
    assert sort_counter(input_dict) == expected_output

def test_sort_counter_negative_values():
    # Dictionary with negative values
    input_dict = {'a': -3, 'b': -1, 'c': -2}
    expected_output = [('a', -3), ('c', -2), ('b', -1)]
    assert sort_counter(input_dict) == expected_output

def test_sort_counter_mixed_types():
    # Dictionary with mixed types (not allowed in Python, but for completeness)
    input_dict = {'a': 3, 'b': '1', 'c': 2}
    expected_output = [('a', 3), ('c', 2), ('b', '1')]
    assert sort_counter(input_dict) == expected_output

def test_sort_counter_duplicate_values():
    # Dictionary with duplicate values
    input_dict = {'a': 3, 'b': 3, 'c': 2}
    expected_output = [('a', 3), ('b', 3), ('c', 2)]
    assert sort_counter(input_dict) == expected_output

